CREATE TABLE IF NOT EXISTS Application (id CHAR(36) PRIMARY KEY,idempotencyKey CHAR(36) NOT NULL UNIQUE,fingerprint CHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,company VARCHAR(200) NOT NULL,phone VARCHAR(40) NOT NULL,email VARCHAR(254) NOT NULL,service VARCHAR(40) NOT NULL,task TEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'NEW',consentAcceptedAt DATETIME NOT NULL,policyVersion VARCHAR(100) NOT NULL,consentVersion VARCHAR(100) NOT NULL,policyHash CHAR(64) NOT NULL,consentHash CHAR(64) NOT NULL,policyText MEDIUMTEXT NOT NULL,consentText TEXT NOT NULL,createdAt DATETIME NOT NULL,expiresAt DATETIME NOT NULL,INDEX (expiresAt)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ApplicationFile (id CHAR(36) PRIMARY KEY,applicationId CHAR(36) NOT NULL,originalName VARCHAR(180) NOT NULL,mime VARCHAR(80) NOT NULL,size INT UNSIGNED NOT NULL,sha256 CHAR(64) NOT NULL,content LONGBLOB NOT NULL,FOREIGN KEY (applicationId) REFERENCES Application(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS NotificationJob (id CHAR(36) PRIMARY KEY,applicationId CHAR(36) NOT NULL UNIQUE,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,nextAttemptAt DATETIME NOT NULL,leaseUntil DATETIME NULL,leaseToken CHAR(36) NULL,lastErrorCode VARCHAR(50) NULL,sentAt DATETIME NULL,INDEX (status,nextAttemptAt),FOREIGN KEY (applicationId) REFERENCES Application(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS RateLimit (`key` VARCHAR(160) PRIMARY KEY,hits INT NOT NULL,expiresAt DATETIME NOT NULL,INDEX (expiresAt)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
